def _axial_load_map(calibration):
    loads = np.asarray(calibration['true_channel_loads'], dtype=float)
    bridge = np.asarray(calibration['bridge_raw'], dtype=float)
    coeff = np.linalg.lstsq(np.column_stack((loads, np.ones(len(loads)))), bridge, rcond=None)[0]
    return (coeff[-1], np.linalg.solve(coeff[:4], np.ones(4)))

def _specimen(group, x, bridge_map):
    (offset, gain) = bridge_map
    return ((group['past_channel_raw'] - offset) @ gain, (group['hold_channel_raw'] - offset) @ gain, np.column_stack((np.ones(len(x)), x)))

def _chamber_response(hold, drift, strain_0, times, taus, weights):
    drift_to_branch = np.array([0.34308, 2.13589])
    amplitudes = hold[:, None] * weights[:2] + drift[:, None] * drift_to_branch
    kernels = -np.expm1(-times[:, None] / taus)
    return (strain_0[:, None] + amplitudes @ kernels.T, amplitudes @ (1.0 / taus))
